export type ManualEntryDraft = {
	type: EntryType,
	slug: string,
	title: string,
	difficulty: Difficulty | null,
	body_markdown: string,
	/**
	 *  `None` → use the active session if any, else fall back to a
	 *  `manual-<workday>-<HHMMSS>` sentinel id.
	 */
	session_id: string | null,
	files_touched: FileTouched[],
	/**  `None` → defaults to `planned`. Spec §3.1. */
	status: EntryStatus | null,
	tags: string[],
	/**
	 *  PR-CI1 — `None` → `manual` (수동 모달의 기존 의미). 훅 기반 자동 초안은
	 *  실측 에이전트(`claude-code` + transcript 의 model)를 넣는다.
	 */
	agent?: AgentRef | null,
	/**
	 *  PR-CI1 — `None` → `true` (수동 모달 = 사용자가 직접 씀). 자동 초안은
	 *  `Some(false)` — 사용자가 UI 에서 검토 후 토글한다.
	 */
	verified_by_user?: boolean | null,
	/**
	 *  Phase 7 (#conversation-import) — 이 기록이 **일어난** 시각(RFC3339).
	 *  `None` → 지금(기존 의미). 들여온 대화는 원본 날짜를 보존해야 하므로
	 *  워크데이 폴더·파일명 `HHMM`·`created_at` 이 전부 이 값에서 나온다.
	 *  파싱 실패는 무시하고 지금으로 떨어진다 — 임포트 한 건 때문에 전체가
	 *  죽는 것보다 날짜 하나가 오늘이 되는 편이 낫다.
	 */
	created_at?: string | null,
};

