	binary_found: boolean,
	binary_path: string | null,
	mcp_json_path: string,
	/**  Claude Desktop `claude_desktop_config.json` 에 붙여넣을 스니펫. */
	desktop_snippet: string,
	/**  우리 것 아닌 MCP 서버 정의 수 (정보 표시용 — 건드리지 않음). */
