export type OculpmStatus = {
	initialized: boolean,
	config_valid: boolean,
	lock_state: LockStateView,
	current_workday: string,
	watcher_state: WatcherStateView,
	/**
	 *  유계 큐가 가득 차 버린 이벤트 누계 — [`WatcherStatus::dropped_total`] 과
	 *  같은 값이다. 여기 실려 오는 이유는 **닥터가 이미 이 봉투를 읽고 있어서**다
	 *  (`DoctorSection`). 전용 커맨드를 새로 내는 대신 한 칸을 늘렸다
	 *  (`{#dropped-total-surface}`).
	 */
	watcher_dropped_total: number,
	/**
	 *  **사용자가 직접** 감시를 멈췄는가 (`{#watcher-user-pause}`).
	 * 
	 *  `watcher_state == Stopped` 만으로는 「뜻하지 않게 멈춤」과 「내가 멈춤」이
	 *  구별되지 않는다 — 앞엣것은 감독관이 60초 안에 되살리고 뒤엣것은 되살리지
	 *  않으니, 화면이 같은 말을 하면 둘 중 하나는 반드시 거짓말이 된다.
	 *  상태 봉투에 칸을 하나 더 낸 이유는 `watcher_dropped_total` 과 같다:
	 *  닥터가 이미 이 봉투를 읽고 있다.
	 * 
	 *  **프로세스 메모리에만 산다** — 앱을 다시 켜면 풀린다
	 *  (`manager::ProjectEntry::user_paused` 주석에 근거).
	 */
	watcher_user_paused: boolean,
	/**
	 *  스케줄링 계측 한 벌 (`{#scheduling-telemetry}`). 봉투에 실리는 이유는
	 *  위 두 칸과 같다 — 닥터가 이미 이 봉투를 읽는다. 워처가 없으면 전부 0.
	 */
	watcher_sched?: WatcherSchedStats,
};

/**
 *  다른 ocul-pm 인스턴스가 이 프로젝트의 락을 가져가, 이 창은 실시간 갱신을
 *  놓았다 (2026-08-23). 예전에는 이런 일이 로그에만 남아, 사용자는 화면이 왜
 *  안 바뀌는지 알 길이 없었다.
 */
export type OculpmWatchYielded = {
	project_id: number,
};

/**
 *  워크데이가 넘어갔다 (완성도 라운드 Phase 4 #events-over-polling). 활성
 *  세션의 경계 타이머와 감독관의 분당 틱이 낸다 — 화면은 60초마다 상태를
 *  다시 묻는 대신 이걸 듣는다. (`OculpmAgentsTemplateChanged` 는 듣는 곳이
 *  없어 같은 라운드에 지웠다.)
 */
export type OculpmWorkdayChanged = {
	project_id: number,
	workday: string,
};

/**
 *  v2 U10 (C1) — 활성 플랜의 미완 항목 한 건 (스탠드업 "오늘 할 일"/"막힘" 소스).
 *  v2 U12 에서 Today "다음 할 일" 위젯도 이 shape 를 소비한다 (workday brief).
 */
export type OpenPlanItem = {
	plan_id: string,
	plan_title: string,
	item_id: string,
	item_title: string,
	/**  항목이 속한 phase 헤딩 (없으면 None — UI 는 플랜 제목으로 폴백). */
	phase: string | null,
	/**  todo | in_progress | blocked */
	status: string,
};

/**  Recent plan activity across all plans — drives the Today "계획 업데이트" block. */
export type PlanActivityDto = {
	plan_id: string,
	plan_title: string,
	item_id: string,
	item_title: string,
	agent_id: string,
	ts: string,
	from_status: string | null,
	to_status: string | null,
	note: string | null,
};

export type PlanDecisionDto = {
	decision_id: string,
	title: string,
	body: string,
	locked_at: string | null,
	agent_id: string | null,
	affects: string[],
};

export type PlanDetail = {
	plan: PlanSummary,
	items: PlanItemDto[],
	phases: PlanPhaseDto[],
	decisions: PlanDecisionDto[],
	/**
	 *  Non-fatal parse warnings (broken glyphs, missing ids, …). Surfaced so
	 *  the UI never fails silently on a malformed plan.
	 */
	warnings: string[],
	/**  「완료 조건」 한 줄 — 없으면 `None` 이 곧 신호다 (머리글이 「없음」을 말한다). */
	done_when: string | null,
	/**  「확인 명령」 한 줄 — 마지막 항목을 닫을 때 돌릴 것. */
	check: string | null,
};

/**
 *  An edit applied by the app / in-app AI to a plan. External agents edit the
 *  `.md` directly per AGENTS.md (PR-PLN 2); this is the in-app equivalent.
 */
export type PlanEditOp = 
/**  Flip an existing item's status. */
{ kind: "set_status"; item_id: string; status: string } | 
/**  Add a new item under a phase (created if absent). */
{ kind: "add_item"; phase: string; title: string; item_id: string | null; status: string | null } | 
/**  Remove an existing item. */
{ kind: "remove_item"; item_id: string } | 
/**  Rename an existing item's title. */
{ kind: "rename_item"; item_id: string; title: string } | 
/**  Rename a phase heading (keeps its items + tracking id). */
{ kind: "rename_phase"; from: string; to: string } | 
/**  Remove a phase heading and every item under it. */
{ kind: "remove_phase"; phase: string } | 
/**  Reorder a phase among its siblings (`up = true` moves it earlier). */
{ kind: "move_phase"; phase: string; up: boolean } | 
/**
 *  Move an item (with its children) — before another item, or to the end
 *  of a phase when `before` is absent (E2, 2026-09-11).
 */
{ kind: "move_item"; item_id: string; phase: string | null; before: string | null };

export type PlanItemDto = {
	item_id: string,
	phase: string | null,
	title: string,
	status: string,
	order_idx: number,
	parent_item: string | null,
	note: string | null,
	last_agent: string | null,
	last_update: string | null,
	/**
	 *  Distinct journal entries linked to this item via the plan-log (the
	 *  agent's `일지` column). Drives the 📓 link + the progress suggestion.
	 */
	journal_refs: string[],
};

export type PlanItemUpdateDto = {
	ts: string,
	item_id: string,
	agent_id: string,
	from_status: string | null,
	to_status: string | null,
	journal_ref: string | null,
	note: string | null,
};

/**  A trackable phase (`## Heading {#id}`) — rollup status + who last touched it. */
export type PlanPhaseDto = {
	phase_id: string | null,
	name: string,
	status: string,
	progress: number | null,
	item_count: number,
	done_count: number,
	last_agent: string | null,
	last_update: string | null,
};

export type PlanScore = {
	active_plans: number,
	with_done_when: number,
	with_check: number,
};

export type PlanSummary = {
	plan_id: string,
	title: string,
	status: string,
	owner_agent: string,
	progress: number | null,
	file_path: string,
	updated_at: string,
	item_count: number,
	done_count: number,
	/**  「마지막 판정」 (`judge.rs`) — 확인 명령을 돌린 가장 최근 결과. 선택 필드(TS `?:`). */
	last_verdict?: PlanVerdict | null,
};

export type PlanVelocity = {
	open_items: number,
	done_last_4w: number,
	weekly_done_avg: number | null,
	eta_weeks: number | null,
	/**
	 *  `oculpm_plan_item_updates` 가 이 프로젝트에 대해 통째로 빈 경우에만
	 *  Some — "플래너를 한 번도 안 그렸다" 는 "최근 4주에 완료가 없다" 와
	 *  다른 사실이라 별도로 알린다.
	 */
	note: string | null,
};

/**  가장 최근 판정 한 줄. */
export type PlanVerdict = {
	passed: boolean,
	/**  판정 표시 뒤의 결과 끝 줄 (`2 failed, 418 passed`). 비어 있을 수 있다. */
	summary: string,
	ts: string,
	agent_id: string,
	item_id: string,
};

export type Project = {
	id: number,
	name: string,
	root_path: string,
	created_at: number,
	/**  아이콘 id (`"terminal"` 등). `None` 이면 프런트가 이름에서 유도한다. */
	icon: string | null,
	/**  색 id (`"amber"` 등) — hex 가 아니라 id 다. */
	color: string | null,
};

export type ProjectStats = {
	files: number,
	chunks: number,
	/**
	 *  Unix seconds of the newest `files.indexed_at` row — `None` when the
	 *  project has never been indexed. f64 because specta has no u64/i64.
	 */
	last_indexed_at: number | null,
};

/**  어디든 열린 프로젝트 집합이 바뀌었다 — 시작 창·프로젝트 목록의 「열림」 표시. */
export type ProjectWindowsChanged = {
	open: number[],
};

export type PromiseScorecard = {
	window_days: number,
	journal: JournalScore,
	plans: PlanScore,
};

/**  한 프로바이더의 마지막 관측. */
export type ProviderReach = {
	provider: string,
	/**  `false` = 마지막 시도가 **서버에 닿지도 못했다** (연결·타임아웃). */
	reachable: boolean,
	/**
	 *  영어 원문 사유. UI 는 이걸 툴팁에 그대로 싣는다 (코드가 아니라 원문이
	 *  필요한 자리 — 사용자가 그대로 검색할 수 있어야 한다).
	 */
	detail: string | null,
	/**  관측 시각 (RFC3339). */
	observed_at: string,
};

export type ReindexReport = {
	project_id: number,
	inserted: number,
	updated: number,
	deleted: number,
	skipped: number,
	completed_at: string,
};

/**
 *  사람이 읽는 근거 — **코드와 파라미터만** 낸다. 번역은 프런트 몫이다
 *  (백엔드가 한국어 문장을 만들면 영어 모드에서 그대로 새어 나온다).
 * 
 *  코드는 셋: `shared_files`(n, 대표 파일) · `plan_item`(항목 id) ·
 *  `title`(일치율 %).
 */
export type RelatedReason = {
	code: string,
	params: string[],
};

export type RelatedRef = {
	/**  Path relative to `.oculpm/journal/` (e.g. `20260522/Bugs/2050_bug_X.md`). */
	ref: string,
	/**  One of `blocks`, `blocked_by`, `followup`, `duplicate`. */
	kind: string,
};

/**  후보 한 건. */
export type RelatedSuggestion = {
	/**  `.oculpm/journal/` 기준 상대경로 — frontmatter `related.ref` 에 그대로 쓴다. */
	relative_path: string,
	title: string,
	workday: string,
	entry_type: string,
	score: number | null,
	reasons: RelatedReason[],
};

export type ReleaseNotesDraft = {
	/**  붙여 넣을 마크다운 한 판. **어디에도 쓰이지 않았다.** */
	markdown: string,
	/**  범위 안 커밋 수. */
	commits: number,
	/**  그 워크데이 범위에서 모은 일지 수. */
	entries: number,
	/**  그중 커밋이 만진 파일과 겹친 일지 수. */
	linked: number,
	/**  실제로 쓰인 기준. `None` = `v*` 태그를 찾지 못해 전체 이력을 읽었다. */
	from_ref: string | null,
	to_ref: string,
	used_llm: boolean,
	/**  사용자에게 알릴 한 줄 (폴백 사유·태그 없음 등). */
	note: string | null,
};

/**  원장 한 줄 — 어느 대화의 시작 컨텍스트에 무엇이 실렸는가. */
export type ResumeDelivery = {
	/**  훅이 적은 UTC ISO 문자열 그대로. */
	ts: string,
	/**  대화 id (훅 payload 의 `session_id`). */
	conversation: string,
	journals: string[],
	plan_items: number,
};

export type ResumeDigest = {
	last_journals: ResumeJournal[],
	next_items: ResumeItem[],
	/**  가장 최근 전달 (대화 단위로 접은 뒤 최신). */
	last_delivery: ResumeDelivery | null,
	/**  창 안에서 전달받은 **대화** 수. */
	deliveries_recent: number,
	/**
	 *  훅이 이 프로젝트에 한 번이라도 닿았다 — 「아직 전달 안 됨」이 "훅이 없다"
	 *  인지 "새 세션이 아직 없다" 인지를 가른다.
	 */
	hooks_seen: boolean,
	/**  복사용 본문 — 같은 자료의 사람용 렌더링 (훅의 컨텍스트와 문장은 다르다). */
	text: string,
};

/**  「이 맥락으로 이어서 작업」의 산출물 — 플래너 ▶실행(`DispatchPrompt`)과 같은 모양. */
export type ResumeDispatch = {
	/**  `.oculpm/index/dispatch/resume.md` (앱 관리·gitignore 영역). */
	file_rel: string,
	/**  셸 프롬프트에 프리필할 한 줄 (`claude "$(cat '…')"`). 실행(Enter)은 사용자가. */
	command: string,
	/**  프롬프트 본문 — 돌고 있는 에이전트가 있으면 이걸 붙여넣는다. */
	prompt: string,
};

export type ResumeItem = {
	plan_id: string,
	plan_title: string,
	/**  플랜의 「완료 조건」 — 항목 너머의 목표 (`planner::done_when`). 없으면 `None`. */
	plan_done_when: string | null,
	item_id: string,
	title: string,
	/**  `todo` · `in_progress` · `blocked`. */
	status: string,
};

export type ResumeJournal = {
	/**  `.oculpm/journal/` 기준 상대경로. */
	relative_path: string,
	title: string,
	created_at: string | null,
	agent_id: string | null,
};

/**  파일 한 판 (본문 포함) — 모달이 렌더한다. */
export type RollupDoc = {
	summary: RollupSummary,
	body_markdown: string,
	/**  이번 호출이 모델을 실제로 썼는가 (읽기에서는 `generator` 에서 파생). */
	used_llm: boolean,
	/**  폴백 사유 등 사용자에게 알릴 한 줄. */
	note: string | null,
};

/**  그 주의 workday 경계 (포함, `YYYYMMDD`). */
export type RollupRange = {
	from: string,
	to: string,
};

/**  목록 한 줄 — 카드·AI 컨텍스트가 파일을 열지 않고 판단할 수 있는 만큼. */
export type RollupSummary = {
	week: string,
	range: RollupRange,
	entry_count: number,
	/**  그 주의 일지가 롤업 생성 이후 바뀌었다 (`entries_hash` 불일치). */
	stale: boolean,
	/**  프로젝트 루트 기준 — `.oculpm/rollups/2026-W38.md`. */
	path: string,
	generator: string,
	/**  「한 주 요약」의 첫 문단. 카드가 접힌 상태로 보여 주는 한 조각. */
	summary: string,
};

export type Session = {
	/**  `YYYYMMDD-NNN`. */
	id: string,
	started_at: string,
	ended_at: string | null,
	ended_reason: EndedReason | null,
	/**
	 *  u32 — caps at ~49 days of continuous active time. A single session
	 *  will never approach this.
	 */
	active_window_ms: number,
	file_event_count: number,
	files_unique: number,
	git_head_at_start: string | null,
	git_head_at_end: string | null,
	agent_label_guess: string | null,
	/**
	 *  이 작업 세션에 붙어 있던 **에이전트 대화 id 전부** (훅의 `session_id`).
	 *  정렬·중복 제거된다. `agent_label_guess` 는 상수 하나라 몇 개가 붙어
	 *  있었는지 말하지 못했다 — 4분할 터미널이 세션 하나로 보이던 이유다.
	 *  파일 이벤트는 여기 쪼개 담지 않는다 (워처는 누가 썼는지 모른다).
	 */
	agent_sessions?: string[],
	/**  Paths relative to `.oculpm/journal/<workday>/`. */
	linked_journal_entries: string[],
};

export type SessionConfig = {
	inactivity_timeout_minutes: number,
	/**
	 *  W4 dogfooding fix — minutes within which new activity after an
	 *  InactivityTimeout finalize will REOPEN the most recent
	 *  inactivity-closed session instead of starting a new one. Bounded by
	 *  today's workday (we never resurrect sessions across the workday
	 *  boundary). `0` disables resume entirely. Defaults to 15 minutes.
	 */
	session_resume_grace_minutes?: number,
};

export type SessionUnrecorded = {
	session_id: string,
	/**  이 세션이 바꿨는데 그날 어떤 일지도 적지 않은 파일 — [`LayerComparison::unrecorded`] 와 같은 판정. */
	unrecorded: string[],
	unrecorded_severity: Severity,
};

/**
 *  설정이 바뀌었다 — **모든 창**이 다시 읽는다.
 * 
 *  창이 여럿이고(크롬식 탭) 트레이 팝오버는 앱 시작 때 한 번 만들어져
 *  세션 내내 살아 있다. 각 창의 `SettingsProvider` 는 마운트 때 한 번만
 *  읽으므로, 이 이벤트가 없으면 한 창에서 테마·언어를 바꿔도 나머지 창과
 *  상단바(트레이 팝오버)는 예전 값을 그대로 그린다.
 */
export type SettingsChanged = {
	keys: string[],
};

export type Severity = "ok" | "warning" | "critical";

export type SummaryStyle = "standup" | "pr_description" | "weekly_status";

/**
 *  PR-R1b (A2) — a symbol hit from `search_symbols` (name LIKE over the AST
 *  symbol index). Unlike `SymbolDef` it carries the owning file path.
 */
export type SymbolSearchResult = {
	name: string,
	kind: string,
	file_path: string,
	start_line: number,
	end_line: number,
};

/**
 *  병합 한 번의 결과. 실패한 파일은 **건너뛰고 이름을 댄다** — 한 건이 막혔다고
 *  나머지를 되돌리면 사용자는 아무것도 못 고친다.
 */
export type TagMergeReport = {
	rewritten: number,
	skipped: TagMergeSkip[],
};

export type TagMergeSkip = {
	/**  `.oculpm/journal/` 기준 상대경로. */
	path: string,
	/**  기계가 읽는 사유 토큰 — 문장은 화면이 만든다 (영어 모드로 새지 않게). */
	reason: string,
};

/**  「태그 정리」 시트의 한 줄 ({#tag-merge}). */
export type TagStat = {
	tag: string,
	count: number,
	/**  이 태그가 붙은 가장 최근 일지의 workday (YYYYMMDD). */
	last_workday: string,
	/**  사전의 어느 말로 모을 만한가. 근거를 못 대면 `None` 이다. */
	suggest_into: string | null,
};

export type TodayDigest = {
	/**  active 플랜만, 최근 갱신 순. */
	plans: DigestPlan[],
	/**  열린 사람 몫 항목 (`[사용자]`·`[사용자 결정]`·`[사용자 액션]`·`[user]` 로 시작). */
	needs_user: DigestItem[],
	/**  막힌(`[!]`) 리프. */
	blocked: DigestItem[],
	journal_plan: JournalPlanLink[],
};

export type TypeCounts = {
	feature: number,
	bug: number,
	error: number,
	refactor: number,
	chore: number,
};

export type Velocity = {
	/**  오래된 주 → 최신 주(오늘이 속한 주) 순, `WeekChart` 와 같은 방향. */
	weeks: WeekBucket[],
	plan: PlanVelocity,
};

export type WatcherConfig = {
	ignore: string[],
	respect_gitignore: boolean,
	debounce_ms: number,
	/**
	 *  Phase 2 `#responsiveness-tiers` — 디바운스를 **이름 있는 정책**으로
	 *  (`fast|balanced|patient|relaxed|deferred|extended`). 값이 있으면
	 *  `debounce_ms` 대신 쓰이고, 없으면 숫자가 그대로 산다 (커스텀 하위호환).
	 *  OS 디바운서에 실제로 걸리는 창은 언제나 `balanced` 로 잘린다 —
	 *  `automation::tiers::os_debounce_ms`.
	 */
	responsiveness?: string | null,
};

/**
 *  워처 하나의 **스케줄링 계측** — perf-baseline §7 이 "없다" 고 적어 둔 것들.
 * 
 *  "런타임 워커가 얼마나 오래 막혀 있었나"(`handle_ms_total` · `handle_max_ms`),
 *  "큐가 얼마나 찼나"(`queue_depth` · `queue_high_water`), "버림이 몇 번
 *  있었나"(`dropped_total`). 전부 워처가 무장한 시각(`started_at`) 이후의
 *  누계이고 리셋하지 않는다 — 다음 기준선 측정이 두 실행을 그대로 견줄 수 있게.
 *  계수기 본체는 `watcher_queue` 의 원자 값이라 뜨거운 길에 잠금이 없다.
 */
export type WatcherSchedStats = {
	/**  워처가 무장한 시각 (RFC 3339). 아래 계수기 전부의 기준점. 워처가 없으면 `None`. */
	started_at: string | null,
	/**  소비 루프가 큐에서 꺼내 처리기에 넘긴 이벤트 누계 (사전 필터 이후, 버림 제외). */
	events_total: number,
	/**  유계 큐가 가득 차 버린 이벤트 누계 — [`WatcherStatus::dropped_total`] 과 같은 값. */
	dropped_total: number,
	/**  지금 큐에 쌓여 있는 이벤트 수. */
	queue_depth: number,
	/**  큐가 가장 깊었던 순간의 이벤트 수. 용량 4,096 에 가까우면 버림의 전조다. */
	queue_high_water: number,
	/**  `handle_event` 안에서 보낸 벽시계 누계 (ms). */
	handle_ms_total: number,
	/**  가장 오래 걸린 `handle_event` 한 번 (ms). */
	handle_max_ms: number,
};

export type WatcherStateView = "running" | "stopped" | "error";

export type WeekBucket = {
	/**  "2026-W38" (월요일이 속한 ISO 주). */
	iso_week: string,
	/**  그 주의 월요일, workday 형식 "YYYYMMDD". */
	from_workday: string,
	/**  그 주의 일요일, workday 형식 "YYYYMMDD". */
	to_workday: string,
	total: number,
	by_type: TypeCounts,
	/**  count 내림차순 → agent_id 오름차순 (동점을 결정적으로). */
	by_agent: AgentCount[],
};

/**
 *  목적지를 실은 창 이동 (딥링크 `oculpm://open` 의 확인 시트가 승인한 뒤).
 *  `view` 는 프런트 `UiV2View` 문자열. 이미 떠 있는 창에는 이벤트로, 갓 만든
 *  창에는 URL(`window_url`)로 실린다 — 갓 만든 창은 아직 리스너가 없다.
 */
export type WindowNavigate = {
	view: string,
	project_id: number | null,
	/**  `.oculpm/` 상대 일지 경로 — 있으면 해당 일지를 연다. */
	entry_path: string | null,
};

/**
 *  한 창의 프로젝트가 바뀌었다 — 시작 창이 프로젝트를 골랐거나, 업데이트 복원이
 *  첫 창에 프로젝트를 실었거나, 지운 프로젝트의 창이 시작 창으로 돌아갔다.
 */
export type WindowProjectChanged = {
	window: string,
	/**  `None` = 시작 창. */
	project_id: number | null,
};

/**
 *  v2 U12 (N3) — Today/저널 타임라인의 단일 집계 응답. 기존에 Today 오픈이
 *  [요일당 list 7회 + 오늘 엔트리당 get 1회 + 플랜당 get 1회 + 365일 히트맵]
 *  = 12+N 회 IPC 를 유발하던 것을 이 커맨드 1회로 대체한다.
 */
export type WorkdayBrief = {
	days: WorkdayBucket[],
	/**
	 *  `focus_workday` 로 지정한 워크데이의 라인 증감 합 (미지정 시 0/0).
	 *  diff 사이드카에서 파생된 값 — 프론트매터 `bytes_*` 가 아니다.
	 */
	lines_added: number,
	lines_removed: number,
	/**  같은 워크데이의 **고유** 파일 수 (미지정 시 0) — 터치 횟수가 아니다. */
	files_touched: number,
	/**  활성 플랜의 미완 항목 (진행중 우선) — Today "다음 할 일" + 스탠드업 공유. */
	open_plan_items: OpenPlanItem[],
	/**  프로젝트 전체 일지 수 (365일 히트맵 대체 스칼라). */
	total_entries: number,
};

/**  v2 U12 (N3) — 워크데이 버킷 하나. */
export type WorkdayBucket = {
	workday: string,
	entries: JournalEntrySummary[],
};

/**
 *  워크데이 하나의 정직성 감사 (완성도 라운드 Phase 3, 2026-08-30).
 * 
 *  [`LayerComparison`] 은 세션 하나를 보지만 Today 는 그날 세션 전부를 물어야
 *  해서 세션 수만큼 IPC 를 날리고, 뒤에서는 같은 `file_changes.ndjson` 을
 *  세션 수만큼 다시 파싱했다. 이 구조체는 ndjson 을 **한 번** 읽고 세션별로
 *  갈라 `unrecorded` 만 낸다 — Today 가 읽는 것은 그것뿐이다.
 */
export type WorkdayComparison = {
	workday: string,
	/**
	 *  그날 index 에 변경을 남긴 세션들 (변경이 없는 세션은 없다). `unrecorded`
	 *  가 빈 세션도 들어 있다 — 화면이 거른다.
	 */
	sessions: SessionUnrecorded[],
	/**  세션 전체에 걸친 `unrecorded` 의 합 (중복 경로는 세션마다 센다). */
	unrecorded_total: number,
};

export type WorkdayConfig = {
	/**  IANA timezone name (e.g. `Asia/Seoul`). */
	timezone: string,
	/**  `HH:MM` 24-hour. Late-night coders may use `03:00`. */
	day_starts_at: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

